const input = $input.first().json;

const fechaEntrega = input.fecha_entrega;
const diasPlazo = parseInt(input.dias_devolucion);
const estado = (input.estado_envio || '').toLowerCase();

if (estado.includes('cancelado')) {
  return [{
    json: {
      status: 'success',
      worker: 'evaluacion_devolucion',
      motivo: null,
      data: {
        procede: false,
        dias_transcurridos: null,
        dias_restantes: null,
        fundamento: 'El pedido figura como cancelado y no admite devolucion.'
      }
    }
  }];
}

if (!fechaEntrega || fechaEntrega.trim() === '' || isNaN(diasPlazo)) {
  return [{
    json: {
      status: 'error',
      worker: 'evaluacion_devolucion',
      motivo: 'datos_insuficientes',
      data: null
    }
  }];
}

const hoy = new Date();
const entrega = new Date(fechaEntrega);
const transcurridos = Math.floor((hoy - entrega) / 86400000);
const restantes = diasPlazo - transcurridos;
const procede = restantes >= 0;

return [{
  json: {
    status: 'success',
    worker: 'evaluacion_devolucion',
    motivo: null,
    data: {
      procede: procede,
      dias_transcurridos: transcurridos,
      dias_restantes: procede ? restantes : 0,
      fundamento: procede
        ? `Entregado hace ${transcurridos} dias. Quedan ${restantes} dias de los ${diasPlazo} del plazo.`
        : `Entregado hace ${transcurridos} dias. El plazo de ${diasPlazo} dias vencio hace ${Math.abs(restantes)} dias.`
    }
  }
}];
